    "terms.h.intellectualProperty": "Propriété intellectuelle",
    "terms.h.privacy": "Confidentialité et protection des données",
    "terms.h.moderation": "Modération et application",
    "terms.h.disputes": "Résolution des litiges",
    "terms.h.termination": "Résiliation",
    "terms.h.liability": "Avertissements et limitation de responsabilité",
    "terms.h.charity": "Engagement caritatif",
