    "privacy.h.transfers": "Transferimet Ndërkombëtare të të Dhënave",
    "privacy.h.rights": "Të Drejtat Tuaja",
    "privacy.h.security": "Siguria e të Dhënave",
    "privacy.h.children": "Privatësia e Fëmijëve",
    "privacy.h.moderation": "Liria e Shprehjes dhe Moderimi i Përmbajtjes",
    "privacy.h.charity": "Angazhimi Bamirës",
